package com.meridian.records;

import java.util.UUID;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class ClaimAmendment {
    private final JdbcTemplate db;
    public ClaimAmendment(JdbcTemplate db) {
        this.db = db;
    }

    public void revise(UUID id, int expected, String caption) {
        if (caption == null || caption.isBlank()) throw new IllegalArgumentException("Missing description");
        // A stale browser must not overwrite a newer change.
        int changed = db.update("update claim set label = ?, revision = revision + 1 "
            + "where id = ? and revision = ?", caption.strip(), id, expected);
        if (changed != 1) {
            throw new IllegalStateException("Record changed or no longer exists");
        }
    }
}

